app.innerHTML='<button id="back">Projects</button><h1></h1><form id="rename-form"><label for="new-project-name">New project name</label><input id="new-project-name"><button type="submit">Rename project</button></form><p id="archived"></p><form id="task-form"><label for="task-title">Task title</label><input id="task-title"><button type="submit">Create task</button></form><div id="alert" class="alert" role="alert"></div><label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select><label for="priority-filter">Priority filter</label><select id="priority-filter"><option>All</option><option>Low</option><option>Normal</option><option>High</option></select><section id="tasks"></section>';
